fn execute_parser_analyze(args: &serde_json::Value, _state: &SynCoreState) -> Result<String> {
    let file_path = args["file_path"]
        .as_str()
        .ok_or_else(|| anyhow::anyhow!("Missing file_path"))?;

    // Use actual parser
    let parser = crate::parser::Parser::new()?;
    match parser.parse_file(std::path::Path::new(file_path)) {
        Ok(structure) => {
            let total_items = structure.functions.len() + structure.classes.len();
            Ok(format!("Parsed: {} ({} items)", file_path, total_items))
        }
        Err(e) => Ok(format!("Failed to parse {}: {}", file_path, e)),
    }
}

fn execute_parser_search(args: &serde_json::Value, _state: &SynCoreState) -> Result<String> {
    let pattern = args["pattern"]
        .as_str()
        .ok_or_else(|| anyhow::anyhow!("Missing pattern"))?;

    // Use ripgrep via std::process
    use std::process::Command;
    let output = Command::new("rg").args(&["--count", pattern, "."]).output();

    match output {
        Ok(out) if out.status.success() => {
            let count = String::from_utf8_lossy(&out.stdout).trim().to_string();
            Ok(format!(
                "Found pattern '{}' in {} locations",
                pattern, count
            ))
        }
        _ => Ok(format!("Pattern search for: {}", pattern)),
    }
}

