#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::{Arc, Mutex};

    #[test]
    fn test_is_write_operation() {
        assert!(is_write_operation("memory_store"));
        assert!(is_write_operation("vector_insert"));
        assert!(is_write_operation("code_index"));
        assert!(!is_write_operation("memory_query"));
        assert!(!is_write_operation("vector_search"));
    }

    #[test]
    fn test_execution_result_creation() {
        let result = ExecutionResult::new();
        assert_eq!(result.steps_executed, 0);
        assert_eq!(result.status, ExecutionStatus::Success);
        assert!(result.error.is_none());
    }

    #[tokio::test]
    async fn test_execute_plan_empty() {
        let embeddings = Box::new(crate::vector::HuggingFaceEmbeddings::new().unwrap());
        let vector_store = Arc::new(Mutex::new(crate::vector::VectorStore::new(embeddings)));
        let state = SynCoreState::with_db_manager(vector_store).unwrap();

        let plan = Plan::new();
        let result = execute_plan(&plan, &state, false).await.unwrap();

        assert_eq!(result.steps_executed, 0);
        assert_eq!(result.status, ExecutionStatus::Success);
    }
}
